rules_version = '2';

service cloud.firestore {
  match /databases/{database}/documents {

    // Tra cứu học sinh, chưa cho web sửa điểm.
    match /students/{studentCode} {
      allow get: if true;
      allow list, create, update, delete: if false;

      // Đọc lịch sử tích điểm.
      match /point_history/{eventId} {
        allow read: if true;
        allow write: if false;
      }
    }

    // Đọc cấu hình thưởng.
    match /reward_settings/{settingId} {
      allow get: if true;
      allow list, create, update, delete: if false;
    }

    // Hỗ trợ luồng thống kê và lấy rác hiện tại.
    match /du_lieu_tram/thong_tin_hien_tai {
      allow read: if true;
      allow create, update: if true;
      allow delete: if false;
    }
  }
}
